void update_ancestors(std::size_t node) {
        if constexpr (std::is_trivially_copyable_v<S> && std::is_copy_constructible_v<S> && std::is_copy_assignable_v<S> && std::is_invocable_r_v<S, decltype(op), const S&, const S&> && sizeof(S) <= 16) {
            std::size_t p = node;
            if (p <= 1) return;
            S value = std::as_const(data_)[p];
            while (p > 1) {
                const S sibling = std::as_const(data_)[p ^ 1];
                const S left = (p & 1) ? sibling : value;
                const S right = (p & 1) ? value : sibling;
                value = std::invoke(op, left, right);
                p >>= 1;
                data_[p] = std::as_const(value);
            }
        } else {
            for (auto p = node >> 1; p; p >>= 1) data_[p] = std::invoke(op, data_[2 * p], data_[2 * p + 1]);
        }
    }
